def flatten(l):
 out={}
 for m in l['concepts'].values():
  for qs in list(m.get('questions',{}).values())+[m.get('repairQuestions',[]),m.get('repairSeedQuestions',[]),m.get('bridgeQuestions',[])]:
   for q in qs:
    id=str(q['id'])
    if id in out:assert out[id]==q
    out[id]=q
 return out
